package forth

import (
	"errors"
	"strconv"
	"strings"
)

// token is either a number (word == "") or a word (word != "").
type token struct {
	num  int
	word string
}

// forth holds the evaluator state: the data stack and the dictionary
// of user-defined words.
type forth struct {
	stack []int
	dict  map[string][]token
}

// Forth evaluates each string in input in order and returns the
// resulting stack.
func Forth(input []string) ([]int, error) {
	f := &forth{
		stack: []int{},
		dict:  make(map[string][]token),
	}
	for _, line := range input {
		if err := f.evalLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

func (f *forth) evalLine(line string) error {
	toks := toTokens(strings.Fields(line))
	if len(toks) == 0 {
		return nil
	}
	if toks[0].word == ":" {
		return f.define(toks[1:])
	}
	return f.exec(toks)
}

// toTokens converts whitespace-separated fields into tokens,
// lowercasing words. Fields that parse as integers are numbers.
func toTokens(fields []string) []token {
	toks := make([]token, 0, len(fields))
	for _, s := range fields {
		if n, err := strconv.Atoi(s); err == nil {
			toks = append(toks, token{num: n})
		} else {
			toks = append(toks, token{word: strings.ToLower(s)})
		}
	}
	return toks
}

// define registers a new word. The body is resolved against the
// dictionary as it stands at definition time, so a word that is
// redefined later does not affect words defined earlier.
func (f *forth) define(toks []token) error {
	if len(toks) < 2 {
		return errors.New("missing word name in definition")
	}
	name := toks[0]
	if name.word == "" {
		return errors.New("cannot redefine a number")
	}
	var body []token
	for _, tok := range toks[1:] {
		if tok.word == ";" {
			f.dict[name.word] = body
			return nil
		}
		if prev, ok := f.dict[tok.word]; ok {
			body = append(body, prev...)
		} else {
			body = append(body, tok)
		}
	}
	return errors.New("missing ; in definition")
}

func (f *forth) exec(toks []token) error {
	for _, tok := range toks {
		if tok.word == "" {
			f.stack = append(f.stack, tok.num)
			continue
		}
		if body, ok := f.dict[tok.word]; ok {
			if err := f.exec(body); err != nil {
				return err
			}
			continue
		}
		if err := f.execBuiltin(tok.word); err != nil {
			return err
		}
	}
	return nil
}

func (f *forth) execBuiltin(word string) error {
	switch word {
	case "+", "-", "*", "/":
		a, b, ok := f.pop2()
		if !ok {
			return errors.New("stack underflow")
		}
		switch word {
		case "+":
			f.stack = append(f.stack, a+b)
		case "-":
			f.stack = append(f.stack, a-b)
		case "*":
			f.stack = append(f.stack, a*b)
		default:
			if b == 0 {
				return errors.New("division by zero")
			}
			f.stack = append(f.stack, a/b)
		}
	case "dup":
		if len(f.stack) < 1 {
			return errors.New("stack underflow")
		}
		f.stack = append(f.stack, f.stack[len(f.stack)-1])
	case "drop":
		if len(f.stack) < 1 {
			return errors.New("stack underflow")
		}
		f.stack = f.stack[:len(f.stack)-1]
	case "swap":
		if len(f.stack) < 2 {
			return errors.New("stack underflow")
		}
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
	case "over":
		if len(f.stack) < 2 {
			return errors.New("stack underflow")
		}
		f.stack = append(f.stack, f.stack[len(f.stack)-2])
	default:
		return errors.New("undefined operation")
	}
	return nil
}

// pop2 returns the two topmost values, a being the one below b.
func (f *forth) pop2() (a, b int, ok bool) {
	if len(f.stack) < 2 {
		return 0, 0, false
	}
	n := len(f.stack)
	a, b = f.stack[n-2], f.stack[n-1]
	f.stack = f.stack[:n-2]
	return a, b, true
}

